import{_ as t,o,c as n,a2 as i}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"RFC 0076 — Design system sizing alignment and new primitive components","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0076-ds-sizing-alignment-and-new-primitives.md"},"headers":[],"relativePath":"rfcs/0076-ds-sizing-alignment-and-new-primitives.md","filePath":"rfcs/0076-ds-sizing-alignment-and-new-primitives.md"}'),a={name:"rfcs/0076-ds-sizing-alignment-and-new-primitives.md"};function s(d,e,r,c,l,h){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="rfc-0076-—-design-system-sizing-alignment-and-new-primitive-components" tabindex="-1">RFC 0076 — Design system sizing alignment and new primitive components <a class="header-anchor" href="#rfc-0076-—-design-system-sizing-alignment-and-new-primitive-components" aria-label="Permalink to &quot;RFC 0076 — Design system sizing alignment and new primitive components&quot;">​</a></h1><p><strong>Status:</strong> Draft<br><strong>Date:</strong> July 2026<br><strong>Author:</strong> Claude Code<br><strong>Scope:</strong> <code>packages/ui</code> (tokens, existing components, new components, Storybook), <code>docs/design-system.md</code>. Builds on <a href="./../research/0004-ui-component-sizing-and-catalog-expansion.html">Research 0004</a>.<br><strong>Incorporated into plan:</strong> No — documentation-first. This RFC covers phases 1–2 of Research 0004&#39;s phased plan only: token/sizing alignment across existing components, plus a curated set of new, non-breaking primitive components. It does not cover the compound-API rework of existing components or the mobile-adapted Combobox/Input OTP — those are separate RFCs per Research 0004&#39;s &quot;Next steps.&quot;</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Align <code>packages/ui</code>&#39;s sizing scale toward a denser, more conventional web-app baseline (control heights, spacing rhythm, font sizes, radii) across existing components, and add 13 new primitive components Sovereign is missing: Switch, Radio Group, Slider, Progress, Separator, Skeleton, Table, Alert, Breadcrumb, Pagination, Kbd, Accordion, Collapsible. Both parts are additive — no existing component&#39;s public API changes, only visual sizing and net-new exports.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Research 0004 found that a wholesale catalog/spec rework conflates three different-risk changes. This RFC scopes the lowest-risk one: a denser sizing scale is a useful rhythm reference, and Sovereign is missing a set of boring, generic primitives (switches, sliders, tables, alerts…) that any plugin building a settings screen, form, or list view will eventually reach for and currently has to hand-roll. Shipping these first, without touching any existing component&#39;s API, delivers real value immediately and establishes the sizing baseline that later, riskier phases (compound-API rework, Combobox/Input OTP) will design against.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li><code>packages/ui/src/tokens/primitives.css</code> already defines a scale that tracks a common 4px/8px spacing rhythm closely: <code>--sv-font-size-sm</code> is 14px, <code>--sv-radius-md</code> is 8px, spacing steps follow the same rhythm. This RFC does not propose new primitive tokens — the scale is already close enough that alignment is mostly about <em>applying</em> it consistently to component dimensions, not redefining it.</li><li><code>Button.module.css</code> already establishes the pattern this RFC generalizes: visual rendered height per size (24/30/36px for sm/md/lg) with <code>min-height: var(--sv-touch-target-min, 44px)</code> as the actual hit target, backed by the <code>--sv-touch-target-min: 44px</code> primitive token. Every new or resized interactive component in this RFC follows the same pattern.</li><li>Two-tier token architecture (primitive → semantic) is documented in <code>docs/design-system.md</code> §&quot;Token architecture&quot; — new components consume semantic tokens only, per existing convention.</li><li><code>packages/ui</code> is currently at <code>0.42.0</code>, published as <code>@sovereignfs/ui</code> under NFR-04.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="part-a-—-sizing-alignment-on-existing-components" tabindex="-1">Part A — sizing alignment on existing components <a class="header-anchor" href="#part-a-—-sizing-alignment-on-existing-components" aria-label="Permalink to &quot;Part A — sizing alignment on existing components&quot;">​</a></h3><p>Audit each existing interactive component (<code>Button</code>, <code>Input</code>, <code>Select</code>, <code>Checkbox</code>, <code>Toggle</code>, <code>SegmentedControl</code>, <code>Tabs</code>, <code>Menu</code> items, <code>Dialog</code> padding/radius, <code>Card</code> padding/radius) against a denser default/sm/lg scale and adjust CSS Module values to match, using the Button pattern as the template: visual size matches the target scale, <code>min-height</code>/hit-area stays at or above <code>--sv-touch-target-min</code>. Where a component doesn&#39;t yet expose size variants (sm/md/lg) that the target scale does, this RFC does not add them speculatively — sizing alignment applies to whatever variants already exist today; adding new size variants to an existing component is a separate, scoped decision (each would itself need a Storybook story update and is arguably an API surface change worth its own review, even if additive).</p><p>This is a visual-only change. No component&#39;s props, exports, or DOM structure change. Under NFR-04&#39;s letter this doesn&#39;t require a version bump (no breaking change), but per its spirit — visible change to a public design system — ships with a minor bump and a <code>design-system.md</code> note so consumers notice at a glance (see Adoption path).</p><h3 id="part-b-—-new-primitive-components" tabindex="-1">Part B — new primitive components <a class="header-anchor" href="#part-b-—-new-primitive-components" aria-label="Permalink to &quot;Part B — new primitive components&quot;">​</a></h3><p>13 new components, each following existing <code>packages/ui</code> conventions (CSS Modules, semantic tokens only, flat controlled-prop API matching the style of <code>Tabs</code>/<code>Toggle</code>/<code>Checkbox</code>, <code>min-height</code>/hit-area on anything interactive, Storybook story + <code>DesignSystemOverview.stories.tsx</code> gallery entry per the Storybook hygiene rule in <code>CLAUDE.md</code>):</p><table tabindex="0"><thead><tr><th>Component</th><th>Notes</th></tr></thead><tbody><tr><td><code>Switch</code></td><td>On/off control, distinct from existing button-style <code>Toggle</code></td></tr><tr><td><code>RadioGroup</code></td><td>Controlled <code>items</code> + <code>value</code>/<code>onChange</code>, same shape as <code>Tabs</code>&#39;s API</td></tr><tr><td><code>Slider</code></td><td>Single-thumb range input; range/dual-thumb deferred until a consumer needs it</td></tr><tr><td><code>Progress</code></td><td>Determinate bar; indeterminate variant only if a consumer needs it</td></tr><tr><td><code>Separator</code></td><td>Horizontal/vertical divider; likely the smallest component in the set</td></tr><tr><td><code>Skeleton</code></td><td>Loading-state placeholder block(s); pairs with existing <code>Spinner</code></td></tr><tr><td><code>Table</code></td><td>Plain semantic table (<code>thead</code>/<code>tbody</code>/<code>tr</code>/<code>td</code> wrappers with DS styling) — explicitly not a full sortable/filterable/virtualized Data Table; see Research 0004&#39;s &quot;full Data Table — Out&quot; decision</td></tr><tr><td><code>Alert</code></td><td>Inline, non-dismissible banner — distinct from <code>Toast</code> (transient) and <code>SystemBanner</code> (instance-wide); fills the &quot;form-level error / explain an empty state&quot; gap <code>sv-ui-design</code>&#39;s ActionResult convention wants</td></tr><tr><td><code>Breadcrumb</code></td><td>Link trail; consumes <code>&lt;Link&gt;</code> per Next.js convention like <code>NavTabs</code> does</td></tr><tr><td><code>Pagination</code></td><td>Page-number / prev-next control</td></tr><tr><td><code>Kbd</code></td><td>Inline keyboard-key styling; trivial, useful once any shortcut/palette surface exists</td></tr><tr><td><code>Accordion</code></td><td>Expand/collapse single or multi-section; keyboard support (Enter/Space to toggle, no arrow-key requirement since sections aren&#39;t a roving-tabindex widget)</td></tr><tr><td><code>Collapsible</code></td><td>Single expand/collapse primitive <code>Accordion</code> composes internally, exported separately since it&#39;s independently useful (e.g. a &quot;show more&quot; toggle)</td></tr></tbody></table><p>All components are net-new exports from <code>@sovereignfs/ui</code> — zero risk to existing consumers.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><p><strong>Bundle Part A and Part B with the compound-API rework (Research 0004 Option A / phase 3).</strong> Rejected per Research 0004&#39;s phased recommendation — mixing an additive, no-risk change with a breaking one forces every consumer to absorb both at once and removes the ability to ship this RFC&#39;s value quickly.</p><p><strong>Skip the sizing audit, only add new components sized to the target scale.</strong> Rejected — would leave existing and new components visually inconsistent with each other (e.g. a densely-sized <code>Switch</code> next to an unaligned <code>Button</code>), undermining the stated goal (&quot;sizes should be the same&quot;) and the actual motivation (visual consistency across the whole DS).</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li>Should <code>Accordion</code> and <code>Collapsible</code> ship together in this RFC&#39;s scope, or should <code>Collapsible</code> land first as the smaller primitive with <code>Accordion</code> as a fast-follow that composes it? (Sizing/risk is identical either way — purely a sequencing question for the eventual epic tasks.)</li><li>Exact per-component size-variant audit (which of sm/md/lg each existing component should expose) is deferred to implementation — this RFC commits to the <em>pattern</em>, not a component-by-component table, to avoid the RFC going stale against the actual token values by the time it&#39;s scheduled.</li></ul><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p>Documentation-first; no <code>ROADMAP.md</code> scheduling commitment yet. Broken down into epic tasks 25.1–25.6 in the new <a href="./../epics/ui-component-parity.html">UI Component Parity</a> epic: one task for Part A (sizing audit), and five tasks for Part B&#39;s component batches (<code>Switch</code>+<code>RadioGroup</code>, <code>Slider</code>+<code>Progress</code>, <code>Table</code>+<code>Alert</code>, <code>Breadcrumb</code>+<code>Pagination</code>+<code>Kbd</code>, <code>Accordion</code>+<code>Collapsible</code>). Each follows normal branch-per-task convention once assigned a roadmap slot.</p><p><strong>Semver:</strong> <code>@sovereignfs/ui</code> takes a <strong>minor</strong> bump under <code>feat/</code> per NFR-04 (new components are a feature addition; the sizing audit is a visual, non-API change but ships in the same bump for consumer visibility). No migration note required in <code>docs/upgrade.md</code> since nothing breaks. Each Storybook story addition follows the existing hygiene rule — <code>DesignSystemOverview.stories.tsx</code> gallery entry + <code>pnpm --filter @sovereignfs/ui typecheck</code> per component PR.</p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>July 2026</td><td>Initial draft</td></tr></tbody></table>',27)])])}const g=t(a,[["render",s]]);export{m as __pageData,g as default};
